begin;
do $$ begin if not exists(select 1 from courses where id='33c5a178-998f-4158-aea9-f8589ade37b0' and name='MVP Engineering' and program='trades' and teacher_email='antoccic@fitchburg.k12.ma.us' and archived_at is null) then raise exception 'Course context changed'; end if; if exists(select 1 from units where id like 'trades-etf-%') then raise exception 'ETF units already exist; inspect before rerunning'; end if; end $$;
insert into public.units(id,name,description,order_index,program,allotted_days,default_start_date) select id,name,description,order_index,program,allotted_days,default_start_date from jsonb_populate_recordset(null::public.units,$etf_data$[{"id": "trades-etf-1", "name": "ETF Project 1: Design a Useful Organizer", "description": "Make a useful product for a real person, test it with their objects, and build a better version. Core strands: trades math, measuring, and drawing/plan interpretation.", "order_index": 1, "program": "trades", "allotted_days": 12, "default_start_date": "2026-09-21"}, {"id": "trades-etf-2", "name": "ETF Project 2: Design a Building of the Future", "description": "Design a model school or community space whose structure and insulated enclosure can be tested and improved. Core strands: trades math, measuring, and drawing/plan interpretation.", "order_index": 2, "program": "trades", "allotted_days": 20, "default_start_date": null}, {"id": "trades-etf-3", "name": "ETF Project 3: Improve a Boat or Fluid Machine", "description": "Build a working fluid-powered device, measure its performance, change one feature, and prove whether it improved. Core strands: trades math, measuring, and drawing/plan interpretation.", "order_index": 3, "program": "trades", "allotted_days": 18, "default_start_date": null}, {"id": "trades-etf-4", "name": "ETF Project 4: Build Electrical Control Systems", "description": "Make a working detector and independently controlled model rooms, then diagnose and improve their circuits. Core strands: trades math, measuring, and drawing/plan interpretation.", "order_index": 4, "program": "trades", "allotted_days": 22, "default_start_date": null}]$etf_data$::jsonb);
insert into public.learning_targets(slug,statement,domain,unit_id,program,content_strand,order_index,exclude_from_growth) select slug,statement,domain,unit_id,program,content_strand,order_index,exclude_from_growth from jsonb_populate_recordset(null::public.learning_targets,$etf_data$[{"slug": "etf26.p1.math", "statement": "I can calculate fractional dimensions, clearance, material area and cost for a useful product.", "domain": "reasoning", "unit_id": "trades-etf-1", "program": "trades", "content_strand": "trade-math", "order_index": 1, "exclude_from_growth": false}, {"slug": "etf26.p1.measure", "statement": "I can measure, lay out and inspect organizer parts from a consistent reference.", "domain": "skill", "unit_id": "trades-etf-1", "program": "trades", "content_strand": "metrology", "order_index": 2, "exclude_from_growth": false}, {"slug": "etf26.p1.plans", "statement": "I can interpret and revise dimensioned part drawings, views and cut lists.", "domain": "skill", "unit_id": "trades-etf-1", "program": "trades", "content_strand": "plan-reading", "order_index": 3, "exclude_from_growth": false}, {"slug": "etf26.p1.build", "statement": "I can build, user-test and physically improve a useful organizer.", "domain": "product", "unit_id": "trades-etf-1", "program": "trades", "content_strand": "engineering-design", "order_index": 4, "exclude_from_growth": false}, {"slug": "etf26.p1.vocabulary", "statement": "I can define and use measurement, drawing, fit and fabrication vocabulary.", "domain": "knowledge", "unit_id": "trades-etf-1", "program": "trades", "content_strand": "plan-reading", "order_index": 5, "exclude_from_growth": false}, {"slug": "etf26.p2.math", "statement": "I can convert feet/inches, scale dimensions, and calculate building quantities and performance change.", "domain": "reasoning", "unit_id": "trades-etf-2", "program": "trades", "content_strand": "trade-math", "order_index": 1, "exclude_from_growth": false}, {"slug": "etf26.p2.measure", "statement": "I can survey a space and check model dimensions, openings and structural/thermal tests.", "domain": "skill", "unit_id": "trades-etf-2", "program": "trades", "content_strand": "metrology", "order_index": 2, "exclude_from_growth": false}, {"slug": "etf26.p2.plans", "statement": "I can interpret coordinated floor plans, elevations, details, symbols and scale.", "domain": "skill", "unit_id": "trades-etf-2", "program": "trades", "content_strand": "plan-reading", "order_index": 3, "exclude_from_growth": false}, {"slug": "etf26.p2.build", "statement": "I can build and improve a model building using structural and thermal test evidence.", "domain": "product", "unit_id": "trades-etf-2", "program": "trades", "content_strand": "engineering-design", "order_index": 4, "exclude_from_growth": false}, {"slug": "etf26.p2.vocabulary", "statement": "I can define and use building, scale, load and insulation vocabulary.", "domain": "knowledge", "unit_id": "trades-etf-2", "program": "trades", "content_strand": "plan-reading", "order_index": 5, "exclude_from_growth": false}, {"slug": "etf26.p3.math", "statement": "I can calculate displacement ratios, volume or distance rates, and performance change.", "domain": "reasoning", "unit_id": "trades-etf-3", "program": "trades", "content_strand": "trade-math", "order_index": 1, "exclude_from_growth": false}, {"slug": "etf26.p3.measure", "statement": "I can measure device geometry and repeatable motion or flow with stated conditions.", "domain": "skill", "unit_id": "trades-etf-3", "program": "trades", "content_strand": "metrology", "order_index": 2, "exclude_from_growth": false}, {"slug": "etf26.p3.plans", "statement": "I can interpret fluid routes, assembly drawings, centerlines and parts lists.", "domain": "skill", "unit_id": "trades-etf-3", "program": "trades", "content_strand": "plan-reading", "order_index": 3, "exclude_from_growth": false}, {"slug": "etf26.p3.build", "statement": "I can build, test, diagnose and physically improve a working fluid device.", "domain": "product", "unit_id": "trades-etf-3", "program": "trades", "content_strand": "engineering-design", "order_index": 4, "exclude_from_growth": false}, {"slug": "etf26.p3.vocabulary", "statement": "I can define and use fluid-system, assembly and performance-test vocabulary.", "domain": "knowledge", "unit_id": "trades-etf-3", "program": "trades", "content_strand": "plan-reading", "order_index": 5, "exclude_from_growth": false}, {"slug": "etf26.p4.math", "statement": "I can calculate wire quantities, relevant circuit relationships, power and energy.", "domain": "reasoning", "unit_id": "trades-etf-4", "program": "trades", "content_strand": "trade-math", "order_index": 1, "exclude_from_growth": false}, {"slug": "etf26.p4.measure", "statement": "I can lay out circuit components and perform demonstrated measurements and inspection.", "domain": "skill", "unit_id": "trades-etf-4", "program": "trades", "content_strand": "metrology", "order_index": 2, "exclude_from_growth": false}, {"slug": "etf26.p4.plans", "statement": "I can interpret circuit symbols, complete paths, control states and physical wiring layouts.", "domain": "skill", "unit_id": "trades-etf-4", "program": "trades", "content_strand": "plan-reading", "order_index": 3, "exclude_from_growth": false}, {"slug": "etf26.p4.build", "statement": "I can build, diagnose and improve a functioning low-voltage control system.", "domain": "product", "unit_id": "trades-etf-4", "program": "trades", "content_strand": "engineering-design", "order_index": 4, "exclude_from_growth": false}, {"slug": "etf26.p4.vocabulary", "statement": "I can define and use electrical-control, schematic, power and energy vocabulary.", "domain": "knowledge", "unit_id": "trades-etf-4", "program": "trades", "content_strand": "plan-reading", "order_index": 5, "exclude_from_growth": false}]$etf_data$::jsonb);
insert into public.mastery_tasks(slug,unit_id,program,prompt,rubric) select slug,unit_id,program,prompt,rubric from jsonb_populate_recordset(null::public.mastery_tasks,$etf_data$[{"slug": "etf26.p1.performance", "unit_id": "trades-etf-1", "program": "trades", "prompt": "Demonstrate your working project and its tested revision. Independently interpret a supplied drawing, solve a trade calculation with units, perform a measurement/layout/inspection, and explain a changed requirement. Use the notebook and physical product; a teammate cannot supply your evidence.", "rubric": {"science": {"description": "Explains the relevant physical behavior and the limits of the classroom model using actual tests."}, "reasoning": {"description": "Independently selects and performs a trade calculation with units and checks its reasonableness."}, "communication": {"description": "Interprets the supplied plan correctly and creates a dimensioned drawing another person can follow."}, "transfer": {"description": "Uses a checked measurement and inspection to implement, retest and explain a physical revision."}}}, {"slug": "etf26.p2.performance", "unit_id": "trades-etf-2", "program": "trades", "prompt": "Demonstrate your working project and its tested revision. Independently interpret a supplied drawing, solve a trade calculation with units, perform a measurement/layout/inspection, and explain a changed requirement. Use the notebook and physical product; a teammate cannot supply your evidence.", "rubric": {"science": {"description": "Explains the relevant physical behavior and the limits of the classroom model using actual tests."}, "reasoning": {"description": "Independently selects and performs a trade calculation with units and checks its reasonableness."}, "communication": {"description": "Interprets the supplied plan correctly and creates a dimensioned drawing another person can follow."}, "transfer": {"description": "Uses a checked measurement and inspection to implement, retest and explain a physical revision."}}}, {"slug": "etf26.p3.performance", "unit_id": "trades-etf-3", "program": "trades", "prompt": "Demonstrate your working project and its tested revision. Independently interpret a supplied drawing, solve a trade calculation with units, perform a measurement/layout/inspection, and explain a changed requirement. Use the notebook and physical product; a teammate cannot supply your evidence.", "rubric": {"science": {"description": "Explains the relevant physical behavior and the limits of the classroom model using actual tests."}, "reasoning": {"description": "Independently selects and performs a trade calculation with units and checks its reasonableness."}, "communication": {"description": "Interprets the supplied plan correctly and creates a dimensioned drawing another person can follow."}, "transfer": {"description": "Uses a checked measurement and inspection to implement, retest and explain a physical revision."}}}, {"slug": "etf26.p4.performance", "unit_id": "trades-etf-4", "program": "trades", "prompt": "Demonstrate your working project and its tested revision. Independently interpret a supplied drawing, solve a trade calculation with units, perform a measurement/layout/inspection, and explain a changed requirement. Use the notebook and physical product; a teammate cannot supply your evidence.", "rubric": {"science": {"description": "Explains the relevant physical behavior and the limits of the classroom model using actual tests."}, "reasoning": {"description": "Independently selects and performs a trade calculation with units and checks its reasonableness."}, "communication": {"description": "Interprets the supplied plan correctly and creates a dimensioned drawing another person can follow."}, "transfer": {"description": "Uses a checked measurement and inspection to implement, retest and explain a physical revision."}}}]$etf_data$::jsonb);
commit; select jsonb_build_object('units',(select count(*) from units where id like 'trades-etf-%'),'targets',(select count(*) from learning_targets where unit_id like 'trades-etf-%'),'tasks',(select count(*) from mastery_tasks where unit_id like 'trades-etf-%'));